        clWhite  := 'FFFFFF';

        clRed    := 'FF0000';
        clBlue   := '0000FF';
        clKhaki  := 'F0E68C';

        clGreen  := '008000';
        clYellow := 'FFFF00';
        clOrange := 'FF6000';

        clGray   := '707070';
        clPink   := 'FF69B4';
        clCyan   := '00FFFF';

        Colors[ 0] := clOrange;
        Colors[ 1] := clYellow;
        Colors[ 2] := clGreen;
        Colors[ 3] := clWhite;
        Colors[ 4] := clCyan;
        Colors[ 5] := clGray;
        Colors[ 6] := clPink;

        Colors[ 7] := clBlue;
        Colors[ 8] := clWhite;
        Colors[ 9] := clRed;
        Colors[10] := clRed;
        Colors[11] := clPink;
        Colors[12] := clCyan;
        Colors[13] := clBlue;

        Colors[14] := clRed;
        Colors[15] := clWhite;
        Colors[16] := clKhaki;
