        Colors[23] := clBlue;
        Colors[24] := clBlue;
        Colors[25] := clCyan;
        Colors[26] := clGray;
        Colors[27] := clKhaki;

        include 'Figures\Scripts\Vectors.inc';

        W := 0.55;
        s3 := sqrt(3);

        N := 7;
        M1 := N div 2; // (N-1) / 2; // 3
        M2 := M1 / 2; // 1.5
        AXA := 2*Pi * M1 / N;

        for i := 0 to 2 do begin
            ax[i] := cos(2 * Pi / 3 * i);
            ay[i] := sin(2 * Pi / 3 * i);
        end;
        az := sqrt(3 / (1 - 2 * cos(AXA)) - 1); // = tan(a); // where a is an angle between axis and horizontal plane

        jAngle := ArcCos((2 * az^2 - 1) / (4 * az^2 + 1));

        VectorRotatePoint(-1/2, s3/2, az,  -2, 0, az,  -2*Pi / N * M2, True);

        DCut2 := (-W * az * Ans_X + W * Ans_Z) / sqrt(1 + az^2);

        VectorRotatePoint(W * az / 2, -W * az * s3 / 2, W,   1,-s3, az,  2*Pi / N * M1, True);
        Mx := DCut2 / sqrt(1 + az^2);
        My :=-Mx * s3;
        Mz := az * Mx;
        k :=-(Mx + az * Mz) / (Ans_X - Mx  + az * Ans_Z - az * Mz);
        DCut1 := ((Mx + (Ans_X - Mx) * k) * Mx + (My + (Ans_Z - My) * k) * My + (Mz + (Ans_Z - Mz) * k) * Mz) / sqrt(Mx^2 + My^2 + Mz^2);

